#include <iostream>
#include <deque>
#include <iterator>
#include <algorithm>

int main() {
    std::deque<int> myDeque;  // A container that supports front insertion
    auto inserter = std::front_inserter(myDeque);  // Compiler instantiates front_insert_iterator<std::deque<int>>
    *inserter = 10;  // This will call myDeque.push_front(10)
    *inserter = 20;  // This will call myDeque.push_front(20) again
    for (const auto& elem : myDeque) {
        std::cout << elem << std::endl;  // Outputs: 20, then 10
    }
    return 0;
}
